import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class BuildOrderPlannerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Map<String, List<String>> map(Object... pairs) {
        Map<String, List<String>> m = new LinkedHashMap<>();
        for (int i = 0; i < pairs.length; i += 2) {
            @SuppressWarnings("unchecked")
            List<String> value = (List<String>) pairs[i + 1];
            m.put((String) pairs[i], value);
        }
        return m;
    }

    static String order(Map<String, List<String>> in) {
        try {
            List<String> out = BuildOrderPlanner.order(in);
            return out == null ? "null" : out.toString();
        } catch (IllegalStateException e) {
            return "CYCLE";
        } catch (RuntimeException e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("simple chain",
                "[core, ui, app]",
                order(map("app", Arrays.asList("core", "ui"), "ui", Arrays.asList("core"),
                        "core", Arrays.asList())));
        check("getting dressed",
                "[shirt, tie, jacket]",
                order(map("shirt", Arrays.asList(), "tie", Arrays.asList("shirt"),
                        "jacket", Arrays.asList("tie", "shirt"))));
        check("implicit task from a prerequisite list",
                "[a, b]",
                order(map("b", Arrays.asList("a"))));
        check("alphabetical tie-break among ready tasks",
                "[alpha, beta, delta, gamma]",
                order(map("gamma", Arrays.asList("delta"), "delta", Arrays.asList("alpha"),
                        "beta", Arrays.asList("alpha"), "alpha", Arrays.asList())));
        check("independent tasks come out sorted",
                "[a, b, c]",
                order(map("c", Arrays.asList(), "a", Arrays.asList(), "b", Arrays.asList())));
        check("duplicate prerequisite is harmless",
                "[a, b]",
                order(map("b", Arrays.asList("a", "a"))));
        check("null prerequisite list means none",
                "[solo]",
                order(map("solo", null)));
        check("empty map", "[]", order(map()));
        check("null map", "[]", order(null));
        check("two-task cycle", "CYCLE", order(map("a", Arrays.asList("b"), "b", Arrays.asList("a"))));
        check("self dependency", "CYCLE", order(map("a", Arrays.asList("a"))));
        check("cycle hidden behind good tasks",
                "CYCLE",
                order(map("ok", Arrays.asList(), "x", Arrays.asList("y"), "y", Arrays.asList("z"),
                        "z", Arrays.asList("x"))));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

