import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;

public class BuildOrderPlanner {

    public static List<String> order(Map<String, List<String>> prerequisites) {
        List<String> result = new ArrayList<>();
        if (prerequisites == null || prerequisites.isEmpty()) {
            return result;
        }

        Map<String, Set<String>> needs = new TreeMap<>();
        Map<String, Set<String>> unlocks = new HashMap<>();
        for (Map.Entry<String, List<String>> entry : prerequisites.entrySet()) {
            needs.computeIfAbsent(entry.getKey(), k -> new TreeSet<>());
            List<String> before = entry.getValue();
            if (before == null) {
                continue;
            }
            for (String earlier : before) {
                needs.computeIfAbsent(earlier, k -> new TreeSet<>());
                needs.get(entry.getKey()).add(earlier);
            }
        }
        for (Map.Entry<String, Set<String>> entry : needs.entrySet()) {
            for (String earlier : entry.getValue()) {
                unlocks.computeIfAbsent(earlier, k -> new HashSet<>()).add(entry.getKey());
            }
        }

        TreeSet<String> ready = new TreeSet<>();
        Map<String, Integer> remaining = new HashMap<>();
        for (Map.Entry<String, Set<String>> entry : needs.entrySet()) {
            remaining.put(entry.getKey(), entry.getValue().size());
            if (entry.getValue().isEmpty()) {
                ready.add(entry.getKey());
            }
        }

        while (!ready.isEmpty()) {
            String next = ready.first();
            ready.remove(next);
            result.add(next);
            for (String later : unlocks.getOrDefault(next, new HashSet<>())) {
                int left = remaining.get(later) - 1;
                remaining.put(later, left);
                if (left == 0) {
                    ready.add(later);
                }
            }
        }

        if (result.size() != needs.size()) {
            throw new IllegalStateException("prerequisites contain a cycle");
        }
        return result;
    }
}
